update_md5_1724e18aeefd2cea20238826306d2.content_md5_1724e18aeefd2cea20238826306d:
export interface DiffLine {
  kind: "context" | "delete" | "insert"
  content: string
}

export interface DiffHunk {
  old_start: number
  old_count: number
  new_start: number
  new_count: number
  lines: DiffLine[]
}

update_md5_4913b65930ae1584132b6e88f18ff.content_md5_4913b65930ae1584132b6e88f18f:
import { describe, expect, test } from "bun:test"
import { initTokenizer } from "@/tokenizers/bpe-wasm"
import { loadDeepSeekV4 } from "@/tokenizers/deepseek-v4/loader"
import { loadQwen3 } from "@/tokenizers/qwen3/loader"

describe("bpe-wasm", () => {
  test("loads tokenizer wasm module", async () => {
    expect(await initTokenizer()).toBeTrue()
  })

  test("loads DeepSeek V4 bundled tokenizer model", async () => {
    const tokenizer = await loadDeepSeekV4()
    expect(tokenizer).toBeDefined()
    const ids = tokenizer!.encode("hello world")
    expect(tokenizer!.countTokens("hello world")).toBeGreaterThan(0)
    expect(ids.length).toBeGreaterThan(0)
    expect(ids.every((id) => Number.isInteger(id))).toBeTrue()
    expect(tokenizer!.decode(ids.slice(0, 5)).length).toBeGreaterThan(0)
  })

  test("loads Qwen3 bundled tokenizer model", async () => {
    const tokenizer = await loadQwen3()
    expect(tokenizer).toBeDefined()
    const ids = tokenizer!.encode("hello world")
    expect(tokenizer!.countTokens("hello world")).toBeGreaterThan(0)
    expect(ids.length).toBeGreaterThan(0)
    expect(ids.every((id) => Number.isInteger(id))).toBeTrue()
    expect(tokenizer!.decode(ids.slice(0, 5)).length).toBeGreaterThan(0)
  })
})

update_md5_d7b2484d4a43ace6a025c6f5d4f27.content_md5_d7b2484d4a43ace6a025c6f5d4f2:
import { describe, expect, test } from "bun:test"
import { computeDiffWasm, createPatch, diffStats, initDiffy } from "../../src/util/diff-wasm"

describe("diff-wasm", () => {
  test("loads diffy wasm module", async () => {
    expect(await initDiffy()).toBeTrue()
  })

  test("creates unified patches with additions", async () => {
    const patch = await createPatch("a\nb", "a\nc\nb")
    expect(patch).not.toBeNull()
    expect(patch!).toContain("+c")
  })

  test("computes addition and deletion stats", async () => {
    expect(await diffStats("a\nb", "a\nc\nb")).toEqual({ additions: 1, deletions: 0 })
    expect(await diffStats("a\nc\nb", "a\nb")).toEqual({ additions: 0, deletions: 1 })
  })

  test("parses diff hunks from diffy output shape", async () => {
    const result = await computeDiffWasm("a\nb", "a\nc\nb")
    expect(result).not.toBeNull()
    expect(result!).toHaveLength(1)
    expect(result![0].old_start).toBe(1)
    expect(result![0].new_start).toBe(1)
    expect(result![0].lines.map((line) => line.kind)).toEqual(["context", "insert", "context"])
  })
})

update_md5_c10ff6a7a22b490af50c8178a2fc7.content_md5_c10ff6a7a22b490af50c8178a2fc:
import { describe, expect, test } from "bun:test"
import { initJsonRepair, repairJsonWasm } from "../../src/util/json-repair-wasm"

describe("json-repair-wasm", () => {
  test("loads json-repair wasm module", async () => {
    expect(await initJsonRepair()).toBeTrue()
  })

  test("repairs malformed object syntax", async () => {
    expect(await repairJsonWasm("{foo: 1, bar: [true,]}")).toBe('{"bar":[true],"foo":1}')
  })
})

update_md5_72ac5e9f6a63ac2392784a7ce9c0e.content_md5_72ac5e9f6a63ac2392784a7ce9c0:
Copy-Item -Recurse -Force "$WasmPkgDir\rdiff" $WasmDistDir Copy-Item -Recurse -Force "$WasmPkgDir\json_repair" $WasmDistDir Copy-Item -Recurse -Force "$WasmPkgDir\diffy" $WasmDistDir Copy-Item -Recurse -Force "$WasmPkgDir\grammars" $WasmDistDir Copy-Item "$WasmPkgDir\tokenizer.wasm" $WasmDistDir
$RequiredWasmAssets = @( "tokenizer.wasm", "diffy\diffy_wasm_bg.wasm", "json_repair\json_repair_bg.wasm", "rdiff\rdiff_bg.wasm", "grammars\tree-sitter-bash.wasm", "grammars\tree-sitter-powershell.wasm" ) foreach ($asset in $RequiredWasmAssets) { $assetPath = Join-Path $WasmDistDir $asset if (-not (Test-Path $assetPath)) { throw "Required WASM asset missing from dist: $asset" } }
Write-Success "WASM modules copied to dist"
